import { test } from "node:test";
import assert from "node:assert/strict";
import { Readable } from "node:stream";
import { importStatement } from "../src/royalties/importer.ts";
import { NdjsonParser } from "../src/royalties/ndjson.ts";

// Serves the statement in fixed-size byte chunks, the way object storage streams a big file.
function chunked(text: string, size: number): Readable {
    const bytes = Buffer.from(text, "utf8");
    const parts: Buffer[] = [];
    for (let i = 0; i < bytes.length; i += size) parts.push(bytes.subarray(i, i + size));
    return Readable.from(parts);
}

const row = (isrc: string, artist: string, track: string, territory: string, streams: number) =>
    JSON.stringify({ isrc, artist, track, territory, streams, revenueMicros: streams * 3_100 });

const STATEMENT = [
    row("ISXXA0000001", "Sigur Rós", "Hoppípolla", "IS", 1200),
    row("GBUM71029604", "Björk", "Jóga", "GB", 800),
    row("JPXX00000777", "坂本龍一", "Merry Christmas Mr. Lawrence", "JP", 650),
    row("ISXXA0000001", "Sigur Rós", "Hoppípolla", "DE", 300),
    row("USSM10000001", "Beyoncé", "Halo", "US", 2000),
    row("GBUM71029604", "Björk", "Jóga", "IS", 100),
].join("\n") + "\n";

const summarize = (s: Awaited<ReturnType<typeof importStatement>>) => s.artists.map((a) => [a.artist, a.streams]);

test("a statement is totalled per artist, highest revenue first", async () => {
    const summary = await importStatement(chunked(STATEMENT, 64 * 1024));
    assert.equal(summary.rows, 6);
    assert.deepEqual(summary.territories, ["DE", "GB", "IS", "JP", "US"]);
    assert.deepEqual(summarize(summary), [["Beyoncé", 2000], ["Sigur Rós", 1500], ["Björk", 900], ["坂本龍一", 650]]);
    assert.equal(summary.artists[0].revenueMicros, 6_200_000);
});

test("CRLF line endings, blank lines and a missing final newline are fine", async () => {
    const text = row("USSM10000001", "Nina Simone", "Feeling Good", "US", 10) + "\r\n\r\n" + row("USSM10000002", "Nina Simone", "Sinnerman", "FR", 5);
    const summary = await importStatement(chunked(text, 16));
    assert.deepEqual(summary.artists, [{ artist: "Nina Simone", streams: 15, revenueMicros: 46_500, tracks: 2 }]);
});

test("totals don't depend on how the file is split into chunks", async () => {
    const whole = summarize(await importStatement(chunked(STATEMENT, 64 * 1024)));
    for (const size of [5, 7, 13, 31]) {
        const split = summarize(await importStatement(chunked(STATEMENT, size)));
        if (JSON.stringify(split) !== JSON.stringify(whole)) console.log(`artists with ${size}-byte chunks:`, split);
        assert.deepEqual(split, whole, `${size}-byte chunks`);
    }
});

test("artist and track names survive a multi-byte character split across chunks", async () => {
    const parser = new NdjsonParser();
    const bytes = Buffer.from(row("ISXXA0000001", "Sigur Rós", "Hoppípolla", "IS", 1) + "\n");
    const cut = bytes.indexOf(Buffer.from("ó")) + 1; // between the two bytes of "ó"
    const out: { value: { artist: string; track: string } }[] = [];
    parser.on("data", (d) => out.push(d));
    parser.write(bytes.subarray(0, cut));
    parser.end(bytes.subarray(cut));
    await new Promise((resolve) => parser.on("end", resolve));
    assert.deepEqual([out[0].value.artist, out[0].value.track], ["Sigur Rós", "Hoppípolla"]);
});

test("a malformed line is reported with its line number", async () => {
    const text = row("USSM10000001", "Nina Simone", "Feeling Good", "US", 10) + "\n{\"isrc\": \"USSM1\n";
    await assert.rejects(importStatement(chunked(text, 8)), /line 2: invalid JSON/);
});

test("a row that fails validation stops the import with its line number", async () => {
    const text = [row("USSM10000001", "Nina Simone", "Feeling Good", "US", 10), row("USSM10000002", "Nina Simone", "Sinnerman", "FR", -4)].join("\n");
    await assert.rejects(importStatement(chunked(text, 64)), /line 2: streams must be a non-negative integer/);
});

test("a large statement read in small chunks matches the expected totals", async () => {
    const artists = ["Rosalía", "Sigur Rós", "Mötley Crüe", "Ólafur Arnalds"];
    const lines: string[] = [];
    for (let i = 0; i < 4000; i++) lines.push(row(`ISXXA${String(i % 50).padStart(7, "0")}`, artists[i % 4], `Track ${i % 50}`, "SE", 1));
    const summary = await importStatement(chunked(lines.join("\n"), 1000));
    assert.deepEqual(summary.artists.map((a) => [a.artist, a.streams]).sort(), artists.map((a) => [a, 1000]).sort());
});
